// Wave shape: Spectagon
// Macro:  Wave(Spectagon, "Erik Loyer & Andy O'Meara", "erik(at)marrowmonkey.com", "", 1)
// Source: pixel/waveshort.sky.h:315
// Author: Erik Loyer & Andy O'Meara  <erik(at)marrowmonkey.com>
// Steps=5  Aspect=0  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_Spectagon(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(5);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = .3;
    a[1] = 10.0;
    a[2] = 1. / a[1];
    a[3] = a[2] / a[1];

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[2] = .03 + a[0]*pow(fft(ux+uy*.0), 1.+ur*.3);
    b[3] = .03 + a[0]*pow(fft(ux+uy*.1), 1.+ur*.3);
    b[4] = .03 + a[0]*pow(fft(ux+uy*.2), 1.+ur*.3);
    b[5] = .03 + a[0]*pow(fft(ux+uy*.3), 1.+ur*.3);
    b[6] = .03 + a[0]*pow(fft(ux+uy*.4), 1.+ur*.3);
    b[7] = .03 + a[0]*pow(fft(ux+uy*.5), 1.+ur*.3);
    b[8] = .03 + a[0]*pow(fft(ux+uy*.6), 1.+ur*.3);
    b[9] = .03 + a[0]*pow(fft(ux+uy*.7), 1.+ur*.3);
    b[10] = .03 + a[0]*pow(fft(ux+uy*.8), 1.+ur*.3);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = cos(s*PI*2 + .6*t);
        c[1] = sin(s*PI*2 + .6*t);
        x[3] = b[2] *c[0] - .8; y[3] = b[2] *c[1]; xyiMax = max(xyiMax, 3);
        x[4] = b[3] *c[0] - .6; y[4] = b[3] *c[1]; xyiMax = max(xyiMax, 4);
        x[5] = b[4] *c[0] - .4; y[5] = b[4] *c[1]; xyiMax = max(xyiMax, 5);
        x[1] = b[5] *c[0] - .2; y[1] = b[5] *c[1]; xyiMax = max(xyiMax, 1);
        x[0] = b[6] *c[0] - .01; y[0] = b[6] *c[1]; xyiMax = max(xyiMax, 0);
        x[2] = b[7] *c[0] + .2; y[2] = b[7] *c[1]; xyiMax = max(xyiMax, 2);
        x[6] = b[8] *c[0] + .4; y[6] = b[8] *c[1]; xyiMax = max(xyiMax, 6);
        x[7] = b[9] *c[0] + .6; y[7] = b[9] *c[1]; xyiMax = max(xyiMax, 7);
        x[8] = b[10]*c[0] + .8; y[8] = b[10]*c[1]; xyiMax = max(xyiMax, 8);
        draw(1, 2, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

// ==============================================================================
// Wave shape: I_Declare
// Macro:  Wave(I_Declare, "", "", "Generator", 1)
// Source: pixel/waveshort.sky.h:344
// Note:   Generator
// Steps=500  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_I_Declare(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(500);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .05 + rnd( .3 );
    a[5] = .05 + rnd( .3 );
    a[1] = trnc( sampleSteps() / 100. );
    a[2] = sampleSteps() / a[1];
    a[3] = 4 + rnd( 7 );
    a[4] = a[3] * ( .4 + rnd( .5 ) );
    a[6] = 2 * PI / a[1];
    a[7] = 2 * tan( PI / a[1] );  // Calc inner radius of the polygon for a side of len 1

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sin( t * a[5] );
    b[1] = cos( t * a[5] );
    b[2] = sin( t * a[0] );
    b[3] = cos( t * a[0] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = a[6] * trnc( s * a[1] );
        c[1] = a[7] * ( wrap( s * a[1] ) - .5 );
        c[2] = 1 + .55 * mag( s * a[1] );
        c[3] = c[2] * cos( c[0] ) - c[1] * sin( c[0] );
        c[4] = c[2] * sin( c[0] ) + c[1] * cos( c[0] );
        c[5] = c[3] * b[1] - c[4] * b[0];  // x
        c[6] = c[3] * b[0] + c[4] * b[1];  // y
        c[7] = c[6]*b[3];  // y
        c[8] = a[3] - c[6]*b[2];
        x[0] = a[4] * c[5] / c[8]; xyiMax = max(xyiMax, 0);
        y[0] = a[4] * c[7] / c[8];
        draw(1, 3, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

