// ==============================================================================
void wave_Critters(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(100);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    // (no A() setup terms)

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    // (no B() frame terms)

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = mag( s ) * 0.35 + .4;  // radius
        c[3] = c[1] * sin( s * 1.57079632 );
        c[2] = c[1] * cos( s * 1.57079632 );
        c[1] = .9 + .3 * mag( .7 * s );
        x[0] = c[2]* .25; y[0] = c[3]* .25; xyiMax = max(xyiMax, 0);
        x[1] = c[2]*-.25; y[1] = c[3]* .25; xyiMax = max(xyiMax, 1);
        x[2] = c[2]*-.25; y[2] = c[3]*-.25; xyiMax = max(xyiMax, 2);
        x[3] = c[2]* .25; y[3] = c[3]*-.25; xyiMax = max(xyiMax, 3);
        x[4] = c[2]* .5; y[4] = c[3]* .5; xyiMax = max(xyiMax, 4);
        x[5] = c[2]*-.5; y[5] = c[3]* .5; xyiMax = max(xyiMax, 5);
        x[6] = c[2]*-.5; y[6] = c[3]* -.5; xyiMax = max(xyiMax, 6);
        x[7] = c[2]* .5; y[7] = c[3]* -.5; xyiMax = max(xyiMax, 7);
        x[8] = c[2]* .75; y[8] = c[3]* .75; xyiMax = max(xyiMax, 8);
        x[9] = c[2]*-.75; y[9] = c[3]* .75; xyiMax = max(xyiMax, 9);
        x[10] = c[2]*-.75; y[10] = c[3]*-.75; xyiMax = max(xyiMax, 10);
        x[11] = c[2]* .75; y[11] = c[3]*-.75; xyiMax = max(xyiMax, 11);
        draw(1, 2, pow(8*dabs(mag(s)),1.5), x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

// ==============================================================================
// Wave shape: Cylinder
// Macro:  Wave(Cylinder, "", "", "Generator.txt", 1)
// Source: pixel/waveshort.sky.h:481
// Note:   Generator.txt
// Steps=512  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_Cylinder(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(512);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 0;
    a[1] = sin( - 3.14 * .4 );  // angle difference from camera
    a[2] = cos( - 3.14 * .4 );
    a[3] = 2 + rnd( 2 );
    a[4] = a[3] * ( .7 + rnd( .3 ) );  // total size
    a[5] = .3 + rnd( .3 );

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * a[5];  // Rotation angle for the grid

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = cos( PI*2* s + b[0] );  // x'
        c[1] = sin( PI*2* s + b[0] );  // y'
        c[2] = .5 * mag( s );
        c[3] = c[1]*a[2] + c[2]*a[1];  // y
        c[4] = a[3] + c[2]*a[2] - c[1]*a[1];  // z
        x[0] = a[4]*c[0]/c[4]; xyiMax = max(xyiMax, 0);
        y[0] = a[4]*c[3]/c[4];
        draw(1, 2, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

