        double s = (double)sint / (double)steps;
        c[1] = 2*s*(1-b[0]);
        c[2] = 2*s*b[0] - 1;
        c[0] = .4 * mag( s );
        x[0] = 1-c[1] +c[0]; xyiMax = max(xyiMax, 0);
        y[0] = -c[2];
        x[1] = c[2]; xyiMax = max(xyiMax, 1);
        y[1] = 1-c[1] +c[0];
        x[2] = c[1]-1 +c[0]; xyiMax = max(xyiMax, 2);
        y[2] = c[2];
        x[3] = -c[2]; xyiMax = max(xyiMax, 3);
