// ==============================================================================
void wave_Splutterbug(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(-1);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = rnd(1.3)+.2;
    a[1] = rnd(clip(a[0]))+(1-clip(a[0]+.02));  // constant
    a[2] = rnd(2*PI);
    a[3] = (rnd(.6)-.3)*trnc(rnd(1)+.7);
    a[4] = trnc(rnd(1)+.5);
    a[5] = a[0]*a[1];

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * 0.0003;
    b[1] = a[2] + t*a[3];
    b[2] = (1+trnc(rnd(1)+.02)*4*a[4]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = s*2*PI+b[0];
        c[1] = mag(s)*b[2] + .1 * beat();
        x[0] = c[1]*cos(c[0]); xyiMax = max(xyiMax, 0);
        y[0] = c[1]*sin(c[0]);
        draw(1, 2, 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

// ==============================================================================
// Wave shape: Orbiting_Stars
// Macro:  Wave(Orbiting_Stars, "Ted", "", "", 1)
// Source: pixel/waveshort.sky.h:1022
// Author: Ted
// Steps=55  Aspect=0  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(3) Detail(4) Density(3) Morphable(3)
// ==============================================================================
void wave_Orbiting_Stars(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(55);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = t;
    a[1] = .09;
    a[2] = flor( rnd( 2 ) + 2 );  // Number of star points (*2)
    a[3] = rnd( .075 ) + .025;
    a[4] = .00025;
    a[5] = rnd( PI );
    a[6] = a[5] + rnd(1 ) + .6;
    a[7] = a[6] + rnd(1 ) + .6;
    a[8] = rnd(.6) + .5;  // initial positioning distances
    a[9] = rnd(.6) + .5;
    a[10] = rnd(.6) + .5;
    a[11] = rnd(2* PI);  // initial movement angles
    a[12] = rnd(2* PI);
    a[13] = rnd(2* PI);
    a[14] = rnd(2) - 1;
    a[15] = rnd(2) - 1;
    a[16] = rnd(2) - 1;
    a[17] = a[8]  * cos(a[5] );
    a[18] = a[8]  * sin(a[5] );
    a[19] = a[9]  * cos(a[6] );
    a[20] = a[9]  * sin(a[6] );
    a[21] = a[10] * cos(a[7] );
    a[22] = a[10] * sin(a[7] );
    a[23] = a[14] * cos(a[11]);
    a[24] = a[14] * sin(a[11]);
    a[25] = a[15] * cos(a[12]);
    a[26] = a[15] * sin(a[12]);
    a[27] = a[16] * cos(a[13]);
    a[28] = a[16] * sin(a[13]);
    a[29] = .2 + rnd( .7 );
    a[30] = sampleSteps() * PI;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sqwv((t - a[0])*60);  // initializer
    b[1] = 1 - b[0];
    b[2] = b[1]*(b[2] + b[17]    + b[19]) + b[0]*a[23];  // movementvector
    b[3] = b[1]*(b[3] + b[18]    + b[20]) + b[0]*a[24];
    b[4] = b[1]* b[4] + b[0]*a[17] + a[4]*b[2];  // iterativeXpos
    b[5] = b[1]* b[5] + b[0]*a[18] + a[4]*b[3];  // iterativeYpos
    b[6] = b[1]*(b[6] - b[21]    - b[17]) + b[0]*a[25];
    b[7] = b[1]*(b[7] - b[22]    - b[18]) + b[0]*a[26];
    b[8] = b[1]* b[8] + b[0]*a[19] + a[4]*b[6];
    b[9] = b[1]* b[9] + b[0]*a[20] + a[4]*b[7];
    b[10] = b[1]*(b[10]+ b[21]    - b[19]) + b[0]*a[27];
    b[11] = b[1]*(b[11]+ b[22]    - b[20]) + b[0]*a[28];
    b[12] = b[1]* b[12]+ b[0]*a[21] + a[4]*b[10];
    b[13] = b[1]* b[13]+ b[0]*a[22] + a[4]*b[11];
    b[14] = sqrt(pow((b[8]  - b[4]),2) + pow((b[9]  - b[5]),2) + a[3]);  // distances
    b[15] = sqrt(pow((b[12] - b[4]),2) + pow((b[13] - b[5]),2) + a[3]);
    b[16] = sqrt(pow((b[12] - b[8]),2) + pow((b[13] - b[9]),2) + a[3]);
    b[17] = (pow(a[1]/b[14],2))*((b[8]  - b[4] )/b[14]);  // gravforce*cos(i.e.x/r
    b[18] = (pow(a[1]/b[14],2))*((b[9]  - b[5] )/b[14]);  // gravforce*sin(i.e.y/r
    b[19] = (pow(a[1]/b[15],2))*((b[12] - b[4] )/b[15]);
    b[20] = (pow(a[1]/b[15],2))*((b[13] - b[5] )/b[15]);
    b[21] = (pow(a[1]/b[16],2))*((b[8]  - b[12])/b[16]);
    b[22] = (pow(a[1]/b[16],2))*((b[9]  - b[13])/b[16]);
    b[23] = (b[4] + b[8] + b[12])/3;  // centeringonscreen
    b[24] = (b[5] + b[9] + b[13])/3;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = sqrt( fft( a[2] * s + t * .25 ) ) * .25;
        c[1] = s * a[30];
        c[2] = c[0] * cos( c[1] ) + b[4] - b[23];
        c[3] = c[0] * sin( c[1] ) + b[5] - b[24];
        c[4] = c[0] * cos( c[1] ) + b[8] - b[23];
        c[5] = c[0] * sin( c[1] ) + b[9] - b[24];
        c[6] = c[0] * cos( c[1] ) + b[12] - b[23];
        c[7] = c[0] * sin( c[1] ) + b[13] - b[24];
        x[0] = c[2]; y[0] = c[3]; xyiMax = max(xyiMax, 0);
        x[1] = c[4]; y[1] = c[5]; xyiMax = max(xyiMax, 1);
        x[2] = c[6]; y[2] = c[7]; xyiMax = max(xyiMax, 2);
        x[3] = -c[2]; y[3] = -c[3]; xyiMax = max(xyiMax, 3);
        x[4] = -c[4]; y[4] = -c[5]; xyiMax = max(xyiMax, 4);
        x[5] = -c[6]; y[5] = -c[7]; xyiMax = max(xyiMax, 5);
        draw(1, 1, a[29], x, y, xyiMax);  // Meta() Reactive(3) Detail(4) Density(3) Morphable(3)
    }
}

